import numpy as np

W1, W2, W3 = W['W1'], W['W2'], W['W3']
rows = range(1, 9)
cols = range(1, 9)

def get_ch(ch):
    A = np.zeros((8, 8, 32))
    for r in rows:
        for c in cols:
            A[r-1, c-1] = W1[(r*10 + c)*5 + ch]
    return A

A0 = get_ch(0)
A1 = get_ch(1)
A2 = get_ch(2)

actions = {1: (-1, 0), 2: (1, 0), 3: (0, -1), 4: (0, 1)}

for name, B in [('ch1', A1), ('ch2', A2)]:
    print('===', name)
    S = {}
    for a in [1, 2, 3, 4]:
        g = W2 @ W3[:, a]          # effective action direction in h1 space
        M = np.zeros((15, 15))
        cnt = np.zeros((15, 15))
        for r in range(8):
            for c in range(8):
                for dr in range(-7, 8):
                    rr = r + dr
                    if rr < 0 or rr >= 8:
                        continue
                    for dc in range(-7, 8):
                        cc = c + dc
                        if cc < 0 or cc >= 8:
                            continue
                        M[dr+7, dc+7] += np.dot(A0[r, c] * B[rr, cc], g)
                        cnt[dr+7, dc+7] += 1
        M = M / np.maximum(cnt, 1)
        mx = np.max(np.abs(M))
        if mx > 0:
            M = M / mx
        S[a] = M

    for a, (dr, dc) in actions.items():
        idx = (dr + 7, dc + 7)
        opp = (-dr + 7, -dc + 7)
        print(f'action {a} dir {dr,dc}: toward {S[a][idx]:+.3f}  opposite {S[a][opp]:+.3f}')

    maxabs = np.max([np.abs(S[a]) for a in S], axis=0)
    inds = np.argsort(maxabs.flatten())[-5:][::-1]
    print('top offsets (dr,dc) and normalized S for actions 1-4:')
    for ind in inds:
        dr = ind // 15 - 7
        dc = ind % 15 - 7
        vals = [S[a][dr+7, dc+7] for a in [1, 2, 3, 4]]
        print(f'  ({dr:+d},{dc:+d}) ' + ' '.join(f'{v:+.3f}' for v in vals))
